module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);

wire [31:0] a_signed, b_signed;
assign a_signed = {a[31], a};
assign b_signed = {b[31], b};

reg [31:0] res;
always @(*) begin
    case (aluc)
        ADD: begin
            {carry, res} = a_signed + b_signed;
            overflow = carry ^ res[31];
        end
        ADDU: begin
            res = a + b;
            carry = 0;
            overflow = 0;
        end
        SUB: begin
            {carry, res} = a_signed - b_signed;
            overflow = carry ^ res[31];
        end
        SUBU: begin
            res = a - b;
            carry = 0;
            overflow = 0;
        end
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: begin
            res = {31'b0, a_signed < b_signed};
            flag = 1'b1;
        end
        SLTU: begin
            res = {31'b0, a < b};
            flag = 1'b1;
        end
        SLL: res = a << b[5:0];
        SRL: res = a >> b[5:0];
        SRA: res = {{b[5]}, a} >>> b[5:0];
        SLLV: res = a << b[5:0];
        SRLV: res = a >> b[5:0];
        SRAV: res = {{b[5]}, a} >>> b[5:0];
        LUI: res = {a[15:0], 16'b0};
        default: res = 32'b0;
    endcase
end

assign r = res;
assign zero = &res ? 1'b0 : 1'b1;
assign negative = res[31];

endmodule
